def main():
    print(f"PLAB count: {len(ALL_PLAB)}")
    print(f"AMC count: {len(ALL_AMC)}")
    print(f"MCCQE count: {len(ALL_MCCQE)}")
    assert len(ALL_PLAB) == 100, f"Expected 100 PLAB, got {len(ALL_PLAB)}"
    assert len(ALL_AMC) == 100, f"Expected 100 AMC, got {len(ALL_AMC)}"
    assert len(ALL_MCCQE) == 100, f"Expected 100 MCCQE, got {len(ALL_MCCQE)}"

    for name, t_list in [("PLAB", ALL_PLAB), ("AMC", ALL_AMC), ("MCCQE", ALL_MCCQE)]:
        for i, t in enumerate(t_list):
            assert len(t) == 6, f"{name} [{i}] len != 6: {t}"
            assert t[1] in TAXONOMY_SUBJECTS, f"{name} [{i}] invalid subject: {t[1]}"
            assert t[2] in TAXONOMY_SYSTEMS, f"{name} [{i}] invalid system: {t[2]}"
            assert t[5].startswith("https://"), f"{name} [{i}] URL not https: {t[5]}"

    target_path = os.path.join(os.path.dirname(os.path.abspath(__file__)), "mega37_topics_b.py")
    with open(target_path, "w", encoding="utf-8") as f:
        f.write("# Auto-generated Mega-Batch 37 Topics Part B\n\n")
        f.write(f"PLAB_TOPICS = {repr(ALL_PLAB)}\n\n")
        f.write(f"AMC_TOPICS = {repr(ALL_AMC)}\n\n")
        f.write(f"MCCQE_TOPICS = {repr(ALL_MCCQE)}\n")

    print(f"Successfully written 100 PLAB, 100 AMC, and 100 MCCQE topics to {target_path}!")


if __name__ == "__main__":
    main()
